+            let t = contour(&rect(0.0, 0.0, 80.0, 80.0), &p).unwrap();
+            holds(&t, 6.0, 5.0, 4, &format!("{side:?} climb={climb} {lead:?}"));
+        }
+    }
+}
+
+#[test]
+fn a_huge_tab_count_fills_the_loop_without_a_huge_allocation() {
